package com.muthumol.player.dummy;
import android.content.*;import android.net.Uri;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Authenticated loopback-only Range server; no permanent copy or internet-facing listener. */
final class StreamHandoff {
 static ServerSocket server;static ExecutorService clients;static volatile boolean stopped=true;
 static void open(PlayerActivity a){Movie movie=a.movie();if(!movie.saveAllowed){Ui.message(a,"External player","This chat does not allow handing media to another app.");return;}if(movie.size<=0){Ui.message(a,"External player","Video size is not available yet.");return;}stop();try{server=new ServerSocket(0,4,InetAddress.getByName("127.0.0.1"));stopped=false;String token=UUID.randomUUID().toString();ServerSocket listener=server;clients=Executors.newFixedThreadPool(2);ReadAheadStore cache=a.session.acquire(movie.fileId);new Thread(()->{while(!stopped)try{Socket client=listener.accept();clients.execute(()->serve(client,cache,token,movie.mime));}catch(Exception e){break;}},"External player stream").start();BackgroundAudio.stream(a);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("http://127.0.0.1:"+listener.getLocalPort()+"/"+token),movie.mime.isEmpty()?"video/*":movie.mime);a.startActivity(Intent.createChooser(intent,"Open stream"));a.player.pause();}catch(Exception e){stop();a.stopService(new Intent(a,BackgroundAudio.class));Ui.message(a,"External player",e.getMessage());}}
 static synchronized void stop(){stopped=true;if(server!=null)try{server.close();}catch(IOException ignored){}server=null;if(clients!=null)clients.shutdownNow();clients=null;}
 static long[] range(String text,long size)throws IOException{if(text==null||text.isEmpty())return new long[]{0,size-1};if(!text.startsWith("bytes=")||text.contains(","))throw new IOException("Invalid Range");String[] parts=text.substring(6).split("-",-1);if(parts.length!=2)throw new IOException("Invalid Range");try{long from=parts[0].isEmpty()?Math.max(0,size-Long.parseLong(parts[1])):Long.parseLong(parts[0]),to=parts[1].isEmpty()||parts[0].isEmpty()?size-1:Long.parseLong(parts[1]);if(from<0||from>=size||to<from)throw new IOException("Range not satisfiable");return new long[]{from,Math.min(to,size-1)};}catch(NumberFormatException e){throw new IOException("Invalid Range");}}
 static void serve(Socket socket,ReadAheadStore cache,String token,String mime){try(Socket client=socket){client.setSoTimeout(10000);BufferedReader in=new BufferedReader(new InputStreamReader(client.getInputStream(),java.nio.charset.StandardCharsets.US_ASCII));String request=in.readLine();if(request==null)return;String[] first=request.split(" ");OutputStream out=client.getOutputStream();if(first.length<2||!first[1].equals("/"+token)||!first[0].equals("GET")&&!first[0].equals("HEAD")){out.write("HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\n\r\n".getBytes("US-ASCII"));return;}String requested="";for(int n=0;n<64;n++){String line=in.readLine();if(line==null||line.isEmpty())break;if(line.length()>8192)return;if(line.toLowerCase(Locale.ROOT).startsWith("range:"))requested=line.substring(6).trim();}long[] range;try{range=range(requested,cache.length);}catch(IOException e){out.write(("HTTP/1.1 416 Range Not Satisfiable\r\nContent-Range: bytes */"+cache.length+"\r\nContent-Length: 0\r\n\r\n").getBytes("US-ASCII"));return;}String header="HTTP/1.1 "+(requested.isEmpty()?"200 OK":"206 Partial Content")+"\r\nAccept-Ranges: bytes\r\nContent-Type: "+(mime.matches("video/[A-Za-z0-9.+-]+")?mime:"video/mp4")+"\r\nContent-Length: "+(range[1]-range[0]+1)+"\r\n"+(requested.isEmpty()?"":"Content-Range: bytes "+range[0]+"-"+range[1]+"/"+cache.length+"\r\n")+"Connection: close\r\n\r\n";out.write(header.getBytes("US-ASCII"));if(first[0].equals("HEAD"))return;byte[] bytes=new byte[65536];long pos=range[0];while(!stopped&&pos<=range[1]){int n=cache.read(pos,bytes,0,(int)Math.min(bytes.length,range[1]-pos+1));if(n<=0)break;out.write(bytes,0,n);pos+=n;}out.flush();}catch(Exception ignored){}}
}
